 "fired.gross":"ברוטו אחרון, ₪ לחודש","fired.tenure":"ותק, שנים","fired.vacdays":"ימי חופשה שלא נוצלו","fired.havdays":"ימי הבראה שלא שולמו",
 "fired.res.pitz":"פיצויי פיטורים","fired.res.notice":"הודעה מוקדמת — ימי חלף הודעה:","fired.res.vac":"פדיון חופשה","fired.res.hav":"דמי הבראה",
